const modal=document.querySelector('#contact-modal');const dialog=modal.querySelector('.modal-dialog');let lastTrigger=null;function openModal(trigger){lastTrigger=trigger;modal.hidden=false;document.body.classList.add('modal-open');dialog.focus()}function closeModal(){modal.hidden=true;document.body.classList.remove('modal-open');lastTrigger?.focus()}document.querySelectorAll('[data-open-modal]').forEach(b=>b.addEventListener('click',()=>openModal(b)));document.querySelectorAll('[data-close-modal]').forEach(b=>b.addEventListener('click',closeModal));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!modal.hidden)closeModal();if(e.key==='Tab'&&!modal.hidden){const focusable=[...dialog.querySelectorAll('button,input')].filter(x=>!x.disabled);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});document.querySelector('#contact-form').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;form.querySelector('.form-status').textContent='Форма заполнена! Это демонстрационный сайт: данные не отправлены.';form.reset()});const menu=document.querySelector('.menu-toggle');const nav=document.querySelector('#main-nav');menu.addEventListener('click',()=>{const isOpen=nav.classList.toggle('is-open');menu.setAttribute('aria-expanded',String(isOpen));menu.setAttribute('aria-label',isOpen?'Закрыть меню':'Открыть меню')});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('is-open');menu.setAttribute('aria-expanded','false')}));
// Change the fixed header from transparent to charcoal after scrolling.
const stickyHeader=document.querySelector('.header-inner');
function updateStickyHeader(){stickyHeader.classList.toggle('scrolled',window.scrollY>24)}
window.addEventListener('scroll',updateStickyHeader,{passive:true});
updateStickyHeader();
